using System;

namespace OmoBench.Installer
{
    /// <summary>
    /// What this installer is, and where it came from.
    ///
    /// The values are stamped in at build time from the git revision being
    /// built (see <c>BuildStamp.cs</c>, generated by build.ps1 and never
    /// committed). Both the installer and the companion payload inside it are
    /// built from that one revision, so "which version is this?" has a single
    /// answer that can be checked against a release.
    ///
    /// Signing is reported, never assumed. An unsigned build says so, in the
    /// installer and in the Apps &amp; features entry: Windows will show it as
    /// an unknown publisher, and claiming otherwise in our own UI would be a
    /// lie the operating system immediately contradicts.
    /// </summary>
    public sealed class BuildInfo
    {
        public string Version;
        public string Revision;
        public string BuiltAt;
        public bool Signed;

        public static BuildInfo Current()
        {
            return new BuildInfo
            {
                Version = BuildStamp.Version,
                Revision = BuildStamp.Revision,
                BuiltAt = BuildStamp.BuiltAt,
                Signed = BuildStamp.Signed,
            };
        }

        /// <summary>
        /// What Apps &amp; features shows as the publisher. Deliberately not a
        /// bare company name while unsigned: there is no verified identity
        /// behind it, and the entry should not imply one.
        /// </summary>
        public static string PublisherDisplayName
        {
            get
            {
                return BuildStamp.Signed
                    ? BuildStamp.SigningIdentity
                    : "OmoBench project (unsigned build)";
            }
        }

        public string ShortRevision
        {
            get
            {
                string revision = Revision ?? "";
                return revision.Length > 12 ? revision.Substring(0, 12) : revision;
            }
        }

        public string Describe()
        {
            return "Version " + (Version ?? "unknown")
                + "\r\nSource revision " + (string.IsNullOrEmpty(Revision) ? "unknown" : Revision)
                + "\r\nBuilt " + (BuiltAt ?? "unknown")
                + "\r\n" + SigningStatement();
        }

        /// <summary>
        /// Said plainly, because the person is about to see a SmartScreen
        /// warning and deserves to know in advance why.
        /// </summary>
        public string SigningStatement()
        {
            if (Signed)
            {
                return "Code signing: signed as " + BuildStamp.SigningIdentity + ".";
            }
            return "Code signing: this build is not signed. Windows will show it as coming from an "
                + "unknown publisher. Check the SHA-256 checksum published with the release before "
                + "running it.";
        }
    }
}
